const fixedLog = []
const pending = commitThenAnnounce(fixedLog)
const syncSnapshot = [...fixedLog]
await pending
--- solution
async function trace() {
  const log = []
  log.push('start')
  setTimeout(() => log.push('timeout'), 0)
  Promise.resolve().then(() => log.push('then'))
  queueMicrotask(() => log.push('microtask'))
  ;(async () => {
    log.push('async body')
    await null
    log.push('after await')
  })()
  log.push('end')
  await new Promise((resolve) => setTimeout(resolve, 20))
  return log
}

// 1. Your prediction, as an array literal of the labels:
const prediction = ['start', 'async body', 'end', 'then', 'microtask', 'after await', 'timeout']

// 2. Make 'commit' happen before 'announce':
async function commitThenAnnounce(log) {
  await new Promise((resolve) =>
    setTimeout(() => {
      log.push('commit')
      resolve()
    }, 0),
  )
  log.push('announce')
}

