function parseCSV(text) {
  const rows = []
  let row = []
  let field = ''
  let inQuotes = false
  let started = false
  for (let i = 0; i < text.length; i++) {
    const c = text[i]
    if (inQuotes) {
      if (c === '"' && text[i + 1] === '"') {
        field += '"'
        i++
      } else if (c === '"') {
        inQuotes = false
      } else {
        field += c
      }
    } else if (c === '"') {
      inQuotes = true
      started = true
    } else if (c === ',') {
      row.push(field)
      field = ''
      started = true
    } else if (c === '\\n') {
      row.push(field)
      rows.push(row)
      row = []
      field = ''
      started = false
    } else if (c !== '\\r') {
      field += c
      started = true
    }
  }
  if (inQuotes) throw new SyntaxError('unterminated quote')
  if (started) {
    row.push(field)
    rows.push(row)
  }
  return rows
}

